	// --- GAME STATE HANDLER ---

	// Logging out or hopping worlds mid-game does not reliably re-send VARBIT_SOUL_WARS_TEAM as 0 on
	// return (varbits are only pushed when the server has a reason to change them, and leaving the game
	// entirely isn't one) — so onVarbitChanged's auto-clear above can never fire for this case. Force a
	// clear directly off the client-state transition instead, so tracked calls don't survive into a game
	// the player is no longer part of.
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGIN_SCREEN && event.getGameState() != GameState.HOPPING) return;
		if (varbitTeam == null && redKills.isEmpty() && blueKills.isEmpty()) return;

		varbitTeam = null;
		if (config.autoClear())
		{
			resetKills();
		}
	}

	// --- OBELISK TRACKING ---

	private void scanForObelisk()
	{
		Scene scene = client.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = client.getPlane();
		for (Tile[] row : tiles[plane])
		{
			for (Tile tile : row)
			{
				if (tile == null) continue;
				for (GameObject obj : tile.getGameObjects())
				{
					if (obj == null) continue;
					int id = obj.getId();
					if (id == OBELISK_ID_NONE || id == OBELISK_ID_BLUE || id == OBELISK_ID_RED)
					{
						trackedObelisk = obj;
						return;
					}
				}
			}
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		int id = event.getGameObject().getId();
		if (id == OBELISK_ID_NONE || id == OBELISK_ID_BLUE || id == OBELISK_ID_RED)
		{
			trackedObelisk = event.getGameObject();
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (event.getGameObject() == trackedObelisk)
		{
			trackedObelisk = null;
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		handleObeliskSacrificeSwap(event);
	}

	private void handleObeliskSacrificeSwap(MenuEntryAdded event)
	{
		if (!config.enableFragging() || !config.preventOffColorDumps() || !obeliskWarnActive) return;
		if (config.dumpOverlayFilter() == ZealgainsConfig.DumpOverlayFilter.SMART_FILTER
				&& !config.alwaysShowDumpOverlay() && !isLocalPlayerInGame()) return;

		String option = event.getOption().toLowerCase();
		if (!option.contains("sacrifice")) return;

		// Match by object ID, or fall back to target name if the ID isn't exposed
		int id = event.getIdentifier();
		boolean isObelisk = (id == OBELISK_ID_NONE || id == OBELISK_ID_BLUE || id == OBELISK_ID_RED)
				|| Text.removeTags(event.getTarget()).toLowerCase().contains("obelisk");

		if (isObelisk)
		{
			event.getMenuEntry().setDeprioritized(true);
		}
	}

	// Promotes Add Friend/Delete to left-click, pushing whatever else is there (Kick, Hop-to, etc.) off left-click.
	// Scoped to the Friends Chat / chat-channel member list only — the standalone Friends List panel uses the
	// same option text but should keep Message as its left-click default, so it must not be touched.
	// Runs on ClientTick (after the menu is fully built for the frame) rather than MenuEntryAdded, since that
	// fires once per entry as the menu is incrementally constructed — too early for the other entries to exist yet.
	//
	// Array position alone is not enough: Add Friend/Delete are natively MenuAction.CC_OP_LOW_PRIORITY, and
	// low-priority entries are right-click only regardless of where they sit in the array. RuneLite's own core
	// Menu Entry Swapper (MenuEntrySwapperPlugin#swap(Menu, MenuEntry[], int, int)) promotes a low-priority
	// entry to CC_OP after moving it into the last slot for exactly this reason — we mirror that here.
	private void reorderFcMemberMenu()
	{
		if (!config.leftClickAddRemove()) return;

		MenuEntry[] entries = client.getMenuEntries();
		int addOrDeleteIndex = -1;
		for (int i = 0; i < entries.length; i++)
		{
			Widget widget = entries[i].getWidget();
			if (widget == null || widget.getId() != InterfaceID.ChatchannelCurrent.LIST) continue;

			String entryOption = entries[i].getOption().toLowerCase();
			if (entryOption.contains("delete") || entryOption.contains("friend"))
			{
				addOrDeleteIndex = i;
				break;
			}
		}
		if (addOrDeleteIndex == -1) return;

		int lastIndex = entries.length - 1;
		MenuEntry addOrDeleteEntry = entries[addOrDeleteIndex];

		if (addOrDeleteIndex != lastIndex)
		{
			MenuEntry displaced = entries[lastIndex];
			entries[addOrDeleteIndex] = displaced;
			entries[lastIndex] = addOrDeleteEntry;
		}

		boolean promoted = addOrDeleteEntry.getType() == MenuAction.CC_OP_LOW_PRIORITY;
		if (promoted)
		{
			addOrDeleteEntry.setType(MenuAction.CC_OP);
		}

		if (addOrDeleteIndex == lastIndex && !promoted) return;

		client.setMenuEntries(entries);
	}

	// --- CHAT MESSAGE HANDLER ---

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		String message = Text.removeTags(event.getMessage()).toLowerCase();

		// Auto-reset on game end — print summary first
		if (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
		{
			if (message.contains("the game has ended") || message.contains("zeal token")
					|| (message.contains("you received") && message.contains("zeal")))
			{
				if (config.autoClear())
				{
					if (config.showGameSummary()) printGameSummary();
					resetKills();
				}
				return;
			}
		}

		if (event.getType() != ChatMessageType.FRIENDSCHAT) return;

		// Only track calls while inside a Soul Wars game (bypassed in dev mode)
		int secondsRemaining = getGameTimeRemaining();
		if (secondsRemaining == -1)
		{
			if (!config.enableCallsOutsideGame()) return;
			secondsRemaining = 0;
		}

		String sender = Text.removeTags(event.getName());

		// Rank broadcast reset — Captain+ only, 15-second cooldown
		if (message.trim().startsWith("!zgreset"))
		{
			FriendsChatManager fcm = client.getFriendsChatManager();
			if (fcm != null)
			{
				FriendsChatRank senderRank = FriendsChatRank.UNRANKED;
				for (FriendsChatMember member : fcm.getMembers())
				{
					if (Text.standardize(member.getName()).equals(Text.standardize(sender)))
					{
						senderRank = member.getRank();
						break;
					}
				}
				if (senderRank.getValue() >= FriendsChatRank.CAPTAIN.getValue())
				{
					long now = System.currentTimeMillis();
					if (now - lastBroadcastReset >= 15_000)
					{
						lastBroadcastReset = now;
						String argsStr = message.trim().substring("!zgreset".length()).trim();
						if (!argsStr.isEmpty())
						{
							String[] broadcastArgs = argsStr.split("\\s+");
							String result = applyTargetedReset(broadcastArgs);
							if (result != null)
							{
								client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
									"<col=" + colorToHex(config.alertCallColor()) + ">Zealgains: " + sender + " reset " + result + "</col>", null);
							}
						}
					}
				}
			}
			return;
		}

		// Runner callouts — decode <gt>/<lt> before tag-stripping so > survives
		String runnerMsg = Text.removeTags(event.getMessage().replace("<gt>", ">").replace("<lt>", "<"))
				.toLowerCase().replaceAll("\\s+", "");
		Matcher runnerMatcher = runnerPattern.matcher(runnerMsg);
		if (runnerMatcher.find())
		{
			String runnerTeam = (runnerMatcher.group(1) != null ? runnerMatcher.group(1) : runnerMatcher.group(2)).toLowerCase();
			if (runnerTeam.equals("r")) redRunners.add(sender);
			else blueRunners.add(sender);
			if (panel != null) panel.updateRunners(redRunners, blueRunners);
			return;
		}

		// Calls must start the message — walk tokens from the beginning, capturing the leading
		// run of same-team call tokens (r1, r123, r1r2r3, "r1 r2 r3", etc.) and stopping at the
		// first token that doesn't start with one. This alone rejects most non-call sentences
		// structurally (e.g. "who has r1?" doesn't start with a call token) without needing a
		// keyword filter. A token only has to *start* with a valid call shape, not match it in
		// full — trailing garbage glued on with no space ("b12\", "b12q") still stops the walk
		// but the call itself still registers, with the garbage folded into the remainder below.
		String[] tokens = message.trim().split("\\s+");
		String callTeam = null;
		StringBuilder callSlots = new StringBuilder();
		int consumedTokens = 0;
		String trailingGarbage = null;
		for (String token : tokens)
		{
			Matcher tokenMatcher = callTokenPattern.matcher(token);
			if (!tokenMatcher.find()) break;
			String t = tokenMatcher.group(1).toLowerCase();
			if (callTeam == null) callTeam = t;
			else if (!callTeam.equals(t)) return; // mixed teams in the leading run — reject
			// group(2) can still contain embedded r/b letters from chains like "r1r2r3" — strip
			// down to digits only before this reaches processCall's char -> slot-number conversion.
			callSlots.append(tokenMatcher.group(2).replaceAll("[^1-5]", ""));
			consumedTokens++;
			if (tokenMatcher.end() < token.length())
			{
				// Garbage glued directly onto the call with no space (e.g. accidentally hitting
				// backslash/quote before Enter) — keep the call, treat the leftover as remainder
				// text subject to the same blocklist as everything else, and stop the call walk.
				trailingGarbage = token.substring(tokenMatcher.end());
				break;
			}
		}
		if (callTeam == null) return; // message doesn't start with a valid call

		// More than one character glued directly onto the call (no space) reads as real text —
		// a username or a word — rather than a fat-fingered keystroke. "b12\" and "b12q" (one
		// stray character) still register; "b12ss" or "b34coolname" (two or more) are rejected
		// outright rather than falling through to the remainder blocklist below.
		if (trailingGarbage != null && trailingGarbage.length() > 1) return;

		// Anything left over after the leading call must not contain a disqualifying word —
		// e.g. "r1 taken by someone else" describes state rather than claiming the slot.
		StringBuilder remainderBuilder = new StringBuilder();
		if (trailingGarbage != null) remainderBuilder.append(trailingGarbage);
		for (int i = consumedTokens; i < tokens.length; i++)
		{
			if (remainderBuilder.length() > 0) remainderBuilder.append(' ');
			remainderBuilder.append(tokens[i]);
		}
		String remainder = remainderBuilder.toString();
		if (remainderContainsBlockedWord(remainder))
		{
			return;
		}

		// Majority world check (uses cached value updated by FC member events)
		if (cachedMajorityWorld != -1 && client.getWorld() != cachedMajorityWorld) return;

		// Cross-world fake call check
		if (config.alertCrossWorld())
		{
			FriendsChatManager fcm = client.getFriendsChatManager();
			if (fcm != null)
			{
				String standardizedSender = Text.standardize(sender).replace('_', ' ');
				for (FriendsChatMember member : fcm.getMembers())
				{
					if (Text.standardize(member.getName()).replace('_', ' ').equals(standardizedSender))
					{
						if (member.getWorld() != client.getWorld())
						{
							sendAlert(sender + " called a fake call from W" + member.getWorld());
							return;
						}
						break;
					}
				}
			}
		}

		String kills = callSlots.toString().replaceAll("[^1-5]", "");
		processCall(callTeam, kills, sender, secondsRemaining);
	}

	// --- COMMANDS ---

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (event.getCommand().equalsIgnoreCase("zgreset"))
		{
			String[] args = event.getArguments();
			if (args == null || args.length == 0)
			{
				SwingUtilities.invokeLater(() ->
				{
					int choice = JOptionPane.showConfirmDialog(
							null,
							"Are you sure you want to reset the entire board?",
							"Zealgains — Confirm Reset",
							JOptionPane.YES_NO_OPTION,
							JOptionPane.WARNING_MESSAGE
					);
					if (choice == JOptionPane.YES_OPTION)
					{
						clientThread.invokeLater(() ->
						{
							resetKills();
							client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: All calls reset.", null);
						});
					}
				});
				return;
			}

			String result = applyTargetedReset(args);
			if (result == null)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: No matching calls found to reset.", null);
			}
			else
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Reset " + result, null);
			}
		}
		else if (event.getCommand().equalsIgnoreCase("zgteam"))
		{
			int varbit = client.getVarbitValue(VARBIT_SOUL_WARS_TEAM);
			String varbitLabel = varbit == 1 ? "blue (1)" : varbit == 2 ? "red (2)" : "none (0)";

			String localName = client.getLocalPlayer() != null
					? Text.removeTags(client.getLocalPlayer().getName()) : null;
			String callTeam = localName != null ? getSenderTeam(localName) : null;

			String resolved = getLocalTeam();

			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"<col=ffff00>Zealgains Team Debug:</col>", null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Varbit 3815: " + varbitLabel, null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Cached varbitTeam: " + (varbitTeam != null ? varbitTeam : "null"), null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Call-history team: " + (callTeam != null ? callTeam : "null"), null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Resolved team: " + (resolved != null ? resolved : "null (alerts suppressed)"), null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  obeliskWarnActive: " + obeliskWarnActive, null);

			String obeliskColor = trackedObelisk == null ? "null"
					: trackedObelisk.getId() == OBELISK_ID_NONE ? "white/uncaptured"
					: trackedObelisk.getId() == OBELISK_ID_BLUE ? "blue"
					: trackedObelisk.getId() == OBELISK_ID_RED ? "red"
					: "unknown (" + trackedObelisk.getId() + ")";
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  trackedObelisk: " + obeliskColor, null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  hasLocalCall: " + hasLocalCall(), null);

			Widget blueHealthW   = client.getWidget(375, 15);
			Widget blueStrengthW = client.getWidget(375, 19);
			Widget redHealthW    = client.getWidget(375, 16);
			Widget redStrengthW  = client.getWidget(375, 20);
			int blueHealth   = blueHealthW != null ? parseWidgetValue(blueHealthW.getText()) : -1;
			int blueStrength = blueStrengthW != null ? parseWidgetValue(blueStrengthW.getText()) : -1;
			int redHealth    = redHealthW != null ? parseWidgetValue(redHealthW.getText()) : -1;
			int redStrength  = redStrengthW != null ? parseWidgetValue(redStrengthW.getText()) : -1;
			boolean blueAvatarReady = isAvatarReady(blueHealth, maxBlueHealth, blueStrength, maxBlueStrength);
			boolean redAvatarReady = isAvatarReady(redHealth, maxRedHealth, redStrength, maxRedStrength);

			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Blue avatar: HP " + blueHealth + "/" + maxBlueHealth
							+ ", Str " + blueStrength + "/" + maxBlueStrength
							+ ", ready=" + blueAvatarReady, null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Red avatar: HP " + redHealth + "/" + maxRedHealth
							+ ", Str " + redStrength + "/" + maxRedStrength
							+ ", ready=" + redAvatarReady, null);

			Widget redKillsW  = client.getWidget(375, 12);
			Widget blueKillsW = client.getWidget(375, 11);
			String redKillsText  = redKillsW != null ? redKillsW.getText() : null;
			String blueKillsText = blueKillsW != null ? blueKillsW.getText() : null;
			// Clamped with Math.max(0, ...) to match how checkAvatarDump() treats these same widgets.
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"  Red kills banked: " + (redKillsText != null ? Math.max(0, parseWidgetValue(redKillsText)) : "?")
							+ ", Blue kills banked: " + (blueKillsText != null ? Math.max(0, parseWidgetValue(blueKillsText)) : "?")
							+ ", dumpWindowOpen=" + isDumpWindowOpen(), null);
		}
		else if (event.getCommand().equalsIgnoreCase("zgsync"))
		{
			if (!config.enableBanList() || config.banListUrl().trim().isEmpty())
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Ban list feature is disabled or URL is missing.", null);
				return;
			}
			long now = System.currentTimeMillis();
			long elapsed = now - lastBanListFetch;
			if (elapsed < BAN_LIST_COOLDOWN_MS)
			{
				long secondsLeft = (BAN_LIST_COOLDOWN_MS - elapsed) / 1000;
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Please wait " + secondsLeft + "s before syncing again.", null);
				return;
			}
			lastBanListFetch = now;
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Fetching latest ban list...", null);
			fetchBanList();
		}
	}

	// --- CALL PROCESSING ---

	private void processCall(String team, String kills, String sender, int secondsRemaining)
	{
		// Team lock: a player may only call for one team
		String lockedTeam = getSenderTeam(sender);
		if (lockedTeam != null && !lockedTeam.equals(team))
		{
			sendAlert(sender + " is locked to " + lockedTeam.toUpperCase() + " team and cannot call for " + team.toUpperCase() + ".");
			return;
		}

		Map<Integer, String> targetMap = team.equals("r") ? redKills : blueKills;
		boolean overCallAlertTriggered = false;

		// Process requested slots in ascending numeric order (1→5) regardless of how they were
		// typed — e.g. "b21" behaves identically to "b12" — so a reversed multi-digit call doesn't
		// trigger a false "out of order" rejection against a slot claimed earlier in the same call.
		boolean[] requested = new boolean[6];
		for (char c : kills.toCharArray())
		{
			requested[Character.getNumericValue(c)] = true;
		}

		for (int killNumber = 1; killNumber <= 5; killNumber++)
		{
			if (!requested[killNumber]) continue;

			if (killNumber == 5 && !validateKill5(team, sender, secondsRemaining)) continue;

			// Sequential check: kill N requires kill N-1 to be claimed first — reject out-of-order calls
			if (killNumber > 1 && !targetMap.containsKey(killNumber - 1))
			{
				sendAlert(sender + " called " + team.toUpperCase() + killNumber + " out of order — " + team.toUpperCase() + (killNumber - 1) + " must be claimed first.");
				continue;
			}

			// Before 12:00, cap at 3 kills — reject and free the slot for others
			if (secondsRemaining > 720 && getKillsClaimedBy(sender) >= 3)
			{
				if (!overCallAlertTriggered)
				{
					sendAlert(sender + " called more than 3 kills before 12:00 — extra calls ignored.");
					overCallAlertTriggered = true;
				}
				continue;
			}

			String existing = targetMap.putIfAbsent(killNumber, sender);
			if (existing == null)
			{
				if (killNumber == 5) kill5Tick = client.getTickCount();
			}
			else
			{
				// Slot already taken — only alert if it's the local player making the duplicate
				alertLocalPlayerConflict(team, killNumber, sender, existing, targetMap);
			}
		}

		if (panel != null) panel.updateKills(redKills, blueKills);
	}

	private boolean validateKill5(String team, String sender, int secondsRemaining)
	{
		if (team.equals("b"))
		{
			if (secondsRemaining > 720)
			{
				sendAlert("B5 CALLED TOO EARLY BY: " + sender);
				return false;
			}
			if (redKills.containsKey(5))
			{
				if (client.getTickCount() == kill5Tick)
				{
					sendAlert("r5 and b5 called at the same time, " + redKills.get(5) + " (r5) wins the call");
				}
				return false;
			}
		}
		else
		{
			if (blueKills.containsKey(5))
			{
				if (client.getTickCount() == kill5Tick)
				{
					blueKills.remove(5);
					sendAlert("r5 and b5 called at the same time, " + sender + " (r5) wins the call");
				}
				else
				{
					sendAlert("R5 called by " + sender + " is invalid — B5 was already called by " + blueKills.get(5));
					return false;
				}
			}
		}
		return true;
	}

	private void alertLocalPlayerConflict(String team, int killNumber, String sender, String existingClaimer, Map<Integer, String> targetMap)
	{
		if (client.getLocalPlayer() == null) return;
		String localName = client.getLocalPlayer().getName();
		if (localName == null) return;
		if (!Text.standardize(sender).equals(Text.standardize(localName))) return;

		String teamLabel = team.toUpperCase();
		int nextSlot = killNumber + 1;
		while (nextSlot <= 5 && targetMap.containsKey(nextSlot)) nextSlot++;

		String suggestion = nextSlot <= 5 ? teamLabel + nextSlot : "a different kill";
		sendAlert(teamLabel + killNumber + " is already taken by " + existingClaimer + " — " + sender + ", please call " + suggestion);
	}

	// --- GAME SUMMARY ---

	private void printGameSummary()
	{
		if (redKills.isEmpty() && blueKills.isEmpty()) return;

		StringBuilder red = new StringBuilder();
		for (int i = 1; i <= 5; i++)
		{
			if (redKills.containsKey(i))
				red.append("R").append(i).append(": ").append(redKills.get(i)).append("  ");
		}

		StringBuilder blue = new StringBuilder();
		for (int i = 1; i <= 5; i++)
		{
			if (blueKills.containsKey(i))
				blue.append("B").append(i).append(": ").append(blueKills.get(i)).append("  ");
		}

		String timeStr = lastKnownGameSeconds >= 0
				? String.format("%d:%02d", lastKnownGameSeconds / 60, lastKnownGameSeconds % 60)
				: "unknown";

		// Prefer live widget read so the score is accurate even if the interface closes on the same tick as game end
		Widget redScoreW  = client.getWidget(375, 12);
		Widget blueScoreW = client.getWidget(375, 11);
		int redScore  = (redScoreW  != null && redScoreW.getText()  != null) ? Math.max(0, parseWidgetValue(redScoreW.getText()))  : lastGameRedScore;
		int blueScore = (blueScoreW != null && blueScoreW.getText() != null) ? Math.max(0, parseWidgetValue(blueScoreW.getText())) : lastGameBlueScore;

		String header  = "<col=" + colorToHex(config.summaryHeaderColor()) + ">=== Zealgains: Game Summary ===</col>";
		String redLine = red.length() > 0   ? "<col=" + colorToHex(config.summaryRedColor())  + ">Red Calls — "  + red.toString().trim()  + "</col>" : null;
		String blueLine = blue.length() > 0 ? "<col=" + colorToHex(config.summaryBlueColor()) + ">Blue Calls — " + blue.toString().trim() + "</col>" : null;
		String scoreLine = "<col=" + colorToHex(config.summaryScoreColor()) + ">Final Score — Red " + redScore + " / Blue " + blueScore
				+ "  -  Time remaining: " + timeStr + "</col>";

		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", header, null);
		if (redLine  != null) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", redLine,  null);
		if (blueLine != null) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", blueLine, null);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", scoreLine, null);
	}

	// --- RESET ---

	// Called from the side panel's Reset button, which runs on the Swing EDT, not the client thread.
	// resetKills() ends up reading live widgets (getGameTimeRemaining() / getLobbyPlayerCount(), both
	// documented "must be captured on the client thread") via panel.updateKills()/updateGameStatus() —
	// calling it directly off-thread was throwing before those reads happened, so the maps got cleared
	// but the panel never repainted, making the reset look like a no-op. Hop onto the client thread first.
	public void resetKillsFromUi()
	{
		clientThread.invokeLater(this::resetKills);
	}

	public void resetKills()
	{
		redKills.clear();
		blueKills.clear();
		redRunners.clear();
		blueRunners.clear();
		disconnectAlerted.clear();

		kill5Tick = -1;
		maxBlueHealth = 0; maxBlueStrength = 0;
		maxRedHealth = 0; maxRedStrength = 0;
		blueAvatarDumpAlerted = false; redAvatarDumpAlerted = false;
		blueEarlyDumpWarned = false; redEarlyDumpWarned = false;
		kill5PreWarnedEarly = false; kill5PreWarnedLate = false;
		trackedObelisk = null; obeliskWarnActive = false;
		lastGameRedScore = 0; lastGameBlueScore = 0; lastKnownGameSeconds = -1;
		lobbyPlayerCount = 0; lobbyCountSet = false; prevLobbyTimerSeconds = -1;

		if (panel != null)
		{
			panel.updateKills(redKills, blueKills);
			panel.updateRunners(redRunners, blueRunners);
			panel.updateGameStatus(-1, 0, 0);
		}
	}

	// --- HELPERS ---

	private int getMajorityWorld(FriendsChatManager fcm)
	{
		if (fcm == null || fcm.getCount() == 0) return -1;

		Map<Integer, Integer> worldCounts = new HashMap<>();
		for (FriendsChatMember member : fcm.getMembers())
		{
			int world = member.getWorld();
			if (world > 0) worldCounts.merge(world, 1, Integer::sum);
		}

		return worldCounts.entrySet().stream()
				.max(Map.Entry.comparingByValue())
				.map(Map.Entry::getKey)
				.orElse(-1);
	}

	// Applies a targeted reset for the given args (e.g. ["r34", "b2"]).
	// Returns a formatted result string like "R3 R4 — B1 moved to B3" or null if nothing matched.
	private String applyTargetedReset(String[] args)
	{
		Pattern resetPattern = Pattern.compile("(?i)^([rb])([1-5]+)$");
		StringBuilder summary = new StringBuilder();
		Set<String> affectedTeams = new LinkedHashSet<>();
		for (String arg : args)
		{
			Matcher m = resetPattern.matcher(arg.trim());
			if (!m.matches()) continue;
			String team = m.group(1).toLowerCase();
			Map<Integer, String> targetMap = team.equals("r") ? redKills : blueKills;
			for (char c : m.group(2).toCharArray())
			{
				int killNum = Character.getNumericValue(c);
				if (targetMap.remove(killNum) != null)
				{
					if (killNum == 5) kill5Tick = -1;
					summary.append(team.toUpperCase()).append(killNum).append(" ");
					affectedTeams.add(team);
				}
			}
		}
		String result = summary.toString().trim();
		if (result.isEmpty()) return null;
		StringBuilder reshuffleMsg = new StringBuilder();
		for (String t : affectedTeams) reshuffleTeam(t, reshuffleMsg);
		if (panel != null) panel.updateKills(redKills, blueKills);
		return reshuffleMsg.length() > 0 ? result + " — " + reshuffleMsg : result;
	}

	private void sendAlert(String message)
	{
		if (config.ruleBreakAlertChat())
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=" + colorToHex(config.alertCallColor()) + ">Zealgains Alert: " + message + "</col>", null);
		notifier.notify(config.enableNotifications(), message);
	}

	private int getKillsClaimedBy(String sender)
	{
		int total = 0;
		for (String player : redKills.values()) if (player.equals(sender)) total++;
		for (String player : blueKills.values()) if (player.equals(sender)) total++;
		return total;
	}

	// Single source of truth for "avatar at full HP+strength" — used by checkAvatarDump() and
	// the ::zgteam debug command so they can never disagree about what "ready" means.
	// A health/strength reading of -1 (widget null/unparseable — e.g. avatar despawned/respawning)
	// always evaluates to not-ready rather than accidentally comparing against an unset max.
	private boolean isAvatarReady(int health, int maxHealth, int strength, int maxStrength)
	{
		return maxHealth > 0 && health >= maxHealth && maxStrength > 0 && strength >= maxStrength;
	}

	// Per-team dump-alert state, read/written by checkTeamDumpAlert() and copied back into the
	// matching blueXxx/redXxx instance fields by checkAvatarDump() right after each call — see the
	// comment on checkTeamDumpAlert() for why these are keyed by avatar (blue/red), not by which
	// team's chat message gets sent.
	private static final class DumpAlertState
	{
		boolean alerted;
		boolean earlyWarned;
	}

	private void checkAvatarDump()
	{
		Widget blueHealthW   = client.getWidget(375, 15);
		Widget blueStrengthW = client.getWidget(375, 19);
		Widget redHealthW    = client.getWidget(375, 16);
		Widget redStrengthW  = client.getWidget(375, 20);

		// Each avatar's widgets read invalid while that avatar is despawned/respawning between
		// kills. Track each value independently instead of bailing the whole tick — otherwise
		// your own avatar respawning would freeze obeliskWarnActive on stale data, even though
		// only the enemy avatar's readiness actually matters for your team's dump decision.
		int blueHealth   = blueHealthW   != null ? parseWidgetValue(blueHealthW.getText())   : -1;
		int blueStrength = blueStrengthW != null ? parseWidgetValue(blueStrengthW.getText()) : -1;
		int redHealth    = redHealthW    != null ? parseWidgetValue(redHealthW.getText())    : -1;
		int redStrength  = redStrengthW  != null ? parseWidgetValue(redStrengthW.getText())  : -1;

		// Track observed maximums so full HP can be detected without hardcoding
		if (blueHealth > maxBlueHealth)     maxBlueHealth   = blueHealth;
		if (blueStrength > maxBlueStrength) maxBlueStrength = blueStrength;
		if (redHealth > maxRedHealth)       maxRedHealth    = redHealth;
		if (redStrength > maxRedStrength)   maxRedStrength  = redStrength;

		// Derive local team — varbit 3815 is authoritative; falls back to call history
		String localTeam = getLocalTeam();

		// Obelisk warning — computed every tick regardless of whether all four max values are set.
		// White obelisk: never safe regardless of team
		boolean obeliskIsUncaptured = trackedObelisk != null && trackedObelisk.getId() == OBELISK_ID_NONE;
		// Opposite-color obelisk: red player on blue obelisk, or blue player on red obelisk
		boolean obeliskIsWrongColor = trackedObelisk != null && localTeam != null
				&& (("r".equals(localTeam) && trackedObelisk.getId() == OBELISK_ID_BLUE)
				||  ("b".equals(localTeam) && trackedObelisk.getId() == OBELISK_ID_RED));

		if (obeliskIsUncaptured || obeliskIsWrongColor)
		{
			obeliskWarnActive = true;
		}
		else if (trackedObelisk == null || localTeam == null)
		{
			obeliskWarnActive = false;
		}
		else if ("r".equals(localTeam))
		{
			boolean blueAvatarReady = isAvatarReady(blueHealth, maxBlueHealth, blueStrength, maxBlueStrength);
			obeliskWarnActive = isObeliskWarnPending(blueAvatarReady, 12);
		}
		else
		{
			boolean redAvatarReady = isAvatarReady(redHealth, maxRedHealth, redStrength, maxRedStrength);
			obeliskWarnActive = isObeliskWarnPending(redAvatarReady, 11);
		}

		// Players in the game without a specific kill call should never dump, even when the
		// avatar reaches full HP (which would otherwise clear obeliskWarnActive for the
		// assigned caller). Keep the warning on for any uncalled participant.
		if (!obeliskWarnActive && trackedObelisk != null && isLocalPlayerInGame() && !hasLocalCall())
		{
			obeliskWarnActive = true;
		}

		// Note: no "all four maxes established" gate here — isAvatarReady() already returns
		// false for whichever side hasn't been observed yet, and the kill-5 pre-warning below
		// doesn't depend on HP/Strength maxes at all, so it shouldn't be blocked by them either.

		// Alerts are always directed at the player's own team — only show if localTeam is known
		boolean showBlueAlert = "r".equals(localTeam); // blue avatar ready → red team dumps
		boolean showRedAlert  = "b".equals(localTeam); // red avatar ready → blue team dumps
		// Dev override (dumpAlertMode=ALL) bypasses the team lock for testing
		if (config.dumpAlertMode() == ZealgainsConfig.DumpAlertMode.ALL)
		{
			showBlueAlert = true;
			showRedAlert  = true;
		}

		// Fragment gate — suppress alert if local player doesn't have enough to dump
		boolean hasEnoughFragments = config.skipFragmentCheck() || getFragmentCount() >= 16;

		// Kill-5 pre-warning — fires at 5:15 then again at 5:05 when:
		//   - Timer has crossed the threshold (315 / 305)
		//   - Dump window is not yet open
		//   - R5 or B5 has been called (winning team known)
		//   - Actual kill count for that team is 4 (kill 5 is genuinely next)
		// No notification. Not gated by avatarAlerts or team filter.
		// Winning team: "DO NOT DUMP UNTIL X ON TIMER"; everyone else: "DO NOT DUMP"
		int preWarnTime = getGameTimeRemaining();
		if (config.enableFragging() && preWarnTime != -1 && !isDumpWindowOpen())
		{
			boolean fireEarly = !kill5PreWarnedEarly && preWarnTime <= 315;
			boolean fireLate  = !kill5PreWarnedLate  && preWarnTime <= 305;
			if (fireEarly || fireLate)
			{
				boolean redHasWin  = redKills.containsKey(5);
				boolean blueHasWin = blueKills.containsKey(5);
				if (redHasWin || blueHasWin)
				{
					Widget rKW = client.getWidget(375, 12);
					String rKT = rKW != null ? rKW.getText() : null;
					int redKillCount  = rKT != null ? Math.max(0, parseWidgetValue(rKT)) : -1;

					Widget bKW = client.getWidget(375, 11);
					String bKT = bKW != null ? bKW.getText() : null;
					int blueKillCount = bKT != null ? Math.max(0, parseWidgetValue(bKT)) : -1;

					boolean killCountReady = (redHasWin && redKillCount == 4)
							|| (blueHasWin && blueKillCount == 4);
					if (killCountReady)
					{
						int pwPlayerCount = lobbyPlayerCount;
						if (pwPlayerCount < 40)
						{
							FriendsChatManager pwFcm = client.getFriendsChatManager();
							if (pwFcm != null) pwPlayerCount = Math.max(pwPlayerCount, pwFcm.getCount());
						}
						String killTimeStr = pwPlayerCount >= 40 ? "4:45" : "5:00";

						boolean localIsWinner = (redHasWin && "r".equals(localTeam))
								|| (blueHasWin && "b".equals(localTeam));
						String winningTeam = redHasWin ? "Red" : "Blue";
						String chatMsg;
						if (localIsWinner)
						{
							chatMsg = "<col=" + colorToHex(config.avatarAlertColor()) + ">Zealgains: " + winningTeam + " team: Do not dump until " + killTimeStr + " on the timer!</col>";
						}
						else if (localTeam == null)
						{
							// Unknown team — generic safety warning
							chatMsg = "<col=" + colorToHex(config.avatarAlertColor()) + ">Zealgains: DO NOT DUMP</col>";
						}
						else
						{
							chatMsg = null; // losing team — this warning is for the other team
						}

						if (fireEarly)
						{
							if (chatMsg != null && config.showKill5PreWarning()) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", chatMsg, null);
							kill5PreWarnedEarly = true;
						}
						if (fireLate)
						{
							if (chatMsg != null && config.showKill5PreWarning()) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", chatMsg, null);
							kill5PreWarnedLate = true;
						}
					}
				}
			}
		}

		// Blue avatar at full → Red team should dump
		boolean blueReady = isAvatarReady(blueHealth, maxBlueHealth, blueStrength, maxBlueStrength);
		DumpAlertState blueSide = new DumpAlertState();
		blueSide.alerted = blueAvatarDumpAlerted;
		blueSide.earlyWarned = blueEarlyDumpWarned;
		checkTeamDumpAlert("Red", blueReady, blueHealth, blueStrength, showBlueAlert, hasEnoughFragments,
				12, redKills, blueSide);
		blueAvatarDumpAlerted = blueSide.alerted;
		blueEarlyDumpWarned = blueSide.earlyWarned;

		// Red avatar at full → Blue team should dump
		boolean redReady = isAvatarReady(redHealth, maxRedHealth, redStrength, maxRedStrength);
		DumpAlertState redSide = new DumpAlertState();
		redSide.alerted = redAvatarDumpAlerted;
		redSide.earlyWarned = redEarlyDumpWarned;
		checkTeamDumpAlert("Blue", redReady, redHealth, redStrength, showRedAlert, hasEnoughFragments,
				11, blueKills, redSide);
		redAvatarDumpAlerted = redSide.alerted;
		redEarlyDumpWarned = redSide.earlyWarned;
	}

	// Once the enemy avatar reaches full HP+Strength, the obelisk warning normally clears —
	// except when this team's own next dump is kill 5 and the dump window hasn't opened yet
	// (5:00, or 4:45 with 40+ in the FC): the warning must stay on past full HP in that case, or
	// players would dump the winning kill too early. ownKillsWidgetChildId is THIS team's own
	// kill counter (375/12 for red, 375/11 for blue) — checking readiness plus this team's own
	// progress is what decides whether kill 5 is genuinely next. Kill-count unreadable (-1) is
	// treated as "possibly 4" rather than risking a false-clear right when it matters most.
	private boolean isObeliskWarnPending(boolean enemyAvatarReady, int ownKillsWidgetChildId)
	{
		if (!enemyAvatarReady) return true;
		Widget killsW = client.getWidget(375, ownKillsWidgetChildId);
		String killText = killsW != null ? killsW.getText() : null;
		int kills = killText != null ? Math.max(0, parseWidgetValue(killText)) : -1;
		return (kills == 4 || kills == -1) && !isDumpWindowOpen();
	}

	// Shared logic for "this avatar just reached full HP+Strength → the OTHER team should dump" —
	// called once per avatar from checkAvatarDump() with the roles swapped. teamLabel/killsWidgetChildId
	// /ownKillsMap all belong to the team being ALERTED (e.g. "Red"/widget 12/redKills when the
	// BLUE avatar — passed as avatarReady/enemyHealth/enemyStrength — is the one that's ready),
	// since that team's own banked kill count and R5/B5 call are what decide which numbered dump
	// this is for them. state is read/written in place; the caller copies it back into the
	// matching blueXxx/redXxx fields (named after the avatar, not the alerted team — see
	// DumpAlertState) immediately after calling.
	private void checkTeamDumpAlert(String teamLabel, boolean avatarReady, int enemyHealth, int enemyStrength,
			boolean showAlert, boolean hasEnoughFragments, int killsWidgetChildId,
			Map<Integer, String> ownKillsMap, DumpAlertState state)
	{
		if (config.enableFragging() && avatarReady && !state.alerted && showAlert && hasEnoughFragments)
		{
			Widget killsW = client.getWidget(375, killsWidgetChildId);
			int nextKill = (killsW != null ? Math.max(0, parseWidgetValue(killsW.getText())) : 0) + 1;
			// Both teams' live kill counters can legitimately sit at 4 at the same time (they're
			// tallied independently) — the R5/B5 call is what actually designates which team is
			// meant to land the winning kill. Kill 5 messaging must therefore respect that call,
			// not just the live counter, or the non-designated team gets told to dump too.
			boolean isCalledWinner = ownKillsMap.containsKey(5);
			// Kill 5 is gated behind the dump window (5:00 / 4:45) — keep checking until it opens
			if (nextKill == 5 && !isDumpWindowOpen())
			{
				// If 40+ people, warn at 5:05 not to dump at 5:00 — must wait until 4:45
				if (isCalledWinner && !state.earlyWarned)
				{
					FriendsChatManager fcm = client.getFriendsChatManager();
					int timeRemaining = getGameTimeRemaining();
					if (fcm != null && fcm.getCount() >= 40 && timeRemaining != -1 && timeRemaining <= 305)
					{
						String warn = teamLabel + " team: 40+ people in FC — do NOT dump at 5:00! Wait until 4:45.";
						if (config.avatarAlertChat()) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=" + colorToHex(config.avatarAlertColor()) + ">Zealgains: " + warn + "</col>", null);
						notifier.notify(config.avatarAlerts(), warn);
						state.earlyWarned = true;
					}
				}
			}
			else
			{
				if (nextKill > 1 && (nextKill != 5 || isCalledWinner))
				{
					String msg;
					if (nextKill == 5)
					{
						FriendsChatManager fcm = client.getFriendsChatManager();
						String timeStr = (fcm != null && fcm.getCount() >= 40) ? "4:45" : "5:00";
						msg = teamLabel + " team: Dump the winning kill at " + timeStr + "!";
					}
					else
					{
						msg = teamLabel + " team: Avatar is ready for the " + ordinal(nextKill) + " dump";
					}
					if (config.avatarAlertChat()) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=" + colorToHex(config.avatarAlertColor()) + ">Zealgains: " + msg + "</col>", null);
					notifier.notify(config.avatarAlerts(), msg);
					state.alerted = true;
				}
			}
		}
		// Only clear the alerted flags on a confirmed drop below full HP/strength — a transient
		// invalid widget read (-1, e.g. a one-tick UI hiccup) must not re-arm the alert, or it
		// would fire a duplicate "avatar ready to dump" message once the reading recovers even
		// though the avatar never actually left full HP.
		else if (enemyHealth >= 0 && enemyStrength >= 0 && !avatarReady)
		{
			state.alerted = false;
			state.earlyWarned = false;
		}
	}

	private String ordinal(int n)
	{
		switch (n)
		{
			case 1:  return "1st";
			case 2:  return "2nd";
			case 3:  return "3rd";
			default: return n + "th";
		}
	}

	private String colorToHex(Color c)
	{
		return String.format("%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	// Returns "r", "b", or null. Priority: varbit 3815 (cached) → equipped cape → call history.
	private String getLocalTeam()
	{
		if (varbitTeam == null)
		{
			int v = client.getVarbitValue(VARBIT_SOUL_WARS_TEAM);
			if (v == 1) varbitTeam = "b";
			else if (v == 2) varbitTeam = "r";
		}
		if (varbitTeam != null) return varbitTeam;

		// Fallback: detect team from equipped Soul Wars cape (blue 25208 / red 25207).
		// Useful for players without a call who haven't triggered a varbit update yet.
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment != null)
		{
			Item cape = equipment.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
			if (cape != null)
			{
				if (cape.getId() == CAPE_ID_BLUE) return "b";
				if (cape.getId() == CAPE_ID_RED)  return "r";
			}
		}

		String localName = client.getLocalPlayer() != null ? Text.removeTags(client.getLocalPlayer().getName()) : null;
		return localName != null ? getSenderTeam(localName) : null;
	}

	private int getFragmentCount()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		if (inv == null) return 0;
		int count = 0;
		for (Item item : inv.getItems())
		{
			if (item != null && item.getId() == SOUL_FRAGMENT_ITEM_ID)
				count += item.getQuantity();
		}
		return count;
	}

	private boolean isDumpWindowOpen()
	{
		int timeRemaining = getGameTimeRemaining();
		if (timeRemaining == -1) return false;
		// lobbyPlayerCount (Players: ## field, frozen at game start) is the most reliable
		// player count; fall back to live FC member count if the lobby wasn't captured.
		int playerCount = lobbyPlayerCount;
		if (playerCount < 40)
		{
			FriendsChatManager fcm = client.getFriendsChatManager();
			if (fcm != null) playerCount = Math.max(playerCount, fcm.getCount());
		}
		return timeRemaining <= (playerCount >= 40 ? 285 : 300);
	}

	private int parseWidgetValue(String text)
	{
		if (text == null || text.isEmpty()) return -1;
		String cleaned = Text.removeTags(text).trim();
		StringBuilder digits = new StringBuilder();
		for (char c : cleaned.toCharArray())
		{
			if (Character.isDigit(c)) digits.append(c);
			else if (digits.length() > 0) break;
		}
		if (digits.length() == 0) return -1;
		try { return Integer.parseInt(digits.toString()); }
		catch (NumberFormatException ignored) { return -1; }
	}

	// Parses lobby countdown format "M:SS" → total seconds; returns -1 on invalid input
	private int parseLobbyTimer(String text)
	{
		if (text == null || text.isEmpty() || text.equals("-")) return -1;
		String cleaned = Text.removeTags(text).trim();
		int colon = cleaned.indexOf(':');
		try
		{
			if (colon > 0)
			{
				int mins = Integer.parseInt(cleaned.substring(0, colon).trim());
				int secs = Integer.parseInt(cleaned.substring(colon + 1).trim());
				return mins * 60 + secs;
			}
			return Integer.parseInt(cleaned);
		}
		catch (NumberFormatException ignored) { return -1; }
	}

	private void reshuffleTeam(String team, StringBuilder alertMsg)
	{
		Map<Integer, String> targetMap = team.equals("r") ? redKills : blueKills;
		String T = team.toUpperCase();

		// Collect remaining callers in slot order
		int[] oldSlots = new int[5];
		String[] callers = new String[5];
		int count = 0;
		for (int i = 1; i <= 5; i++)
		{
			String caller = targetMap.get(i);
			if (caller != null) { oldSlots[count] = i; callers[count] = caller; count++; }
		}

		if (count == 0) return;

		// Check for gaps
		boolean hasGaps = false;
		for (int i = 0; i < count; i++)
			if (oldSlots[i] != i + 1) { hasGaps = true; break; }
		if (!hasGaps) return;

		// Rebuild compacted from slot 1
		targetMap.clear();
		StringBuilder moves = new StringBuilder();
		for (int i = 0; i < count; i++)
		{
			int newSlot = i + 1;
			targetMap.put(newSlot, callers[i]);
			if (oldSlots[i] != newSlot)
			{
				if (oldSlots[i] == 5) kill5Tick = -1;
				if (moves.length() > 0) moves.append(", ");
				moves.append(T).append(oldSlots[i]).append(" moved to ").append(T).append(newSlot);
			}
		}

		// Open slots in compact form e.g. "R45"
		// Blue caps at 4 unless timer is at/below 12:00 and R5 hasn't been claimed
		int timeRemaining = getGameTimeRemaining();
		int maxSlot = (team.equals("b") && (timeRemaining == -1 || timeRemaining > 720 || redKills.containsKey(5))) ? 4 : 5;
		StringBuilder open = new StringBuilder(T);
		for (int i = count + 1; i <= maxSlot; i++) open.append(i);

		if (alertMsg.length() > 0) alertMsg.append(" | ");
		alertMsg.append(moves);
		if (open.length() > 1) alertMsg.append(", need ").append(open);
	}

	private String getSenderTeam(String sender)
	{
		String std = Text.standardize(sender);
		for (String player : redKills.values())  if (Text.standardize(player).equals(std)) return "r";
		for (String player : blueKills.values()) if (Text.standardize(player).equals(std)) return "b";
		return null;
	}

	// See CALL_REMAINDER_BLOCKLIST for the word list and why it's checked at all.
	private boolean remainderContainsBlockedWord(String remainder)
	{
		for (String word : CALL_REMAINDER_BLOCKLIST)
		{
			if (remainder.contains(word)) return true;
		}
		return false;
	}

	private String cleanOsrsName(String input)
	{
		if (input == null) return "";
		return Text.standardize(input)
				.replace('_', ' ')
				.replace('-', ' ')
				.replaceAll("[^a-z0-9 ]", "")
				.trim();
	}

	// --- WIDGET / TIMER ---

	public int getGameTimeRemaining()
	{
		Widget timeWidget = client.getWidget(375, 23);
		if (timeWidget == null || timeWidget.isHidden()) return -1;

		String rawText = timeWidget.getText();
		if (rawText == null || rawText.isEmpty()) return -1;

		String text = Text.removeTags(rawText).trim();
		if (!text.matches("\\d+:\\d{2}")) return -1;

		try
		{
			String[] parts = text.split(":");
			return (Integer.parseInt(parts[0]) * 60) + Integer.parseInt(parts[1]);
		}
		catch (NumberFormatException ignored) { return -1; }
	}

	public boolean isInSoulWarsGame()
	{
		return getGameTimeRemaining() != -1;
	}

	// --- CHAT HIGHLIGHT ---

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (config.pmCheckerHighlight() || config.highlightOnFl() || config.enableBanList())
		{
			refreshChatHighlights();
		}
		reorderFcMemberMenu();
	}

	private void refreshChatHighlights()
	{
		Widget chatList = client.getWidget(InterfaceID.ChatchannelCurrent.LIST);
		if (chatList == null || chatList.isHidden()) return;

		for (Widget child : chatList.getDynamicChildren())
		{
			String rawText = child.getText();
			if (rawText == null || rawText.isEmpty()) continue;
			if (rawText.startsWith("World ") || rawText.matches("^W\\d+$")) continue;

			String cleanName = Text.removeTags(rawText).trim();
			String std = cleanOsrsName(cleanName);

			java.awt.Color colorToSet = null;

			if (config.enableBanList() && bannedPlayers.contains(std))
				colorToSet = config.banListColor();
			else if (config.pmCheckerHighlight() && client.isFriended(cleanName, true))
				colorToSet = config.pmCheckerColor();
			else if (config.highlightOnFl() && client.isFriended(cleanName, false))
				colorToSet = config.flHighlightColor();

			if (colorToSet != null)
			{
				if (rawText.contains("<col=") || rawText.contains("</col>"))
				{
					child.setText(rawText.replaceAll("(?i)<col=[^>]+>", "").replace("</col>", ""));
				}
				child.setTextColor(colorToSet.getRGB());
			}
		}
	}

	// --- BAN LIST FETCH ---

	private void fetchBanList()
	{
		if (!config.enableBanList() || config.banListUrl().trim().isEmpty())
		{
			bannedPlayers.clear();
			return;
		}

		String baseUrl = config.banListUrl().trim();
		String requestUrl = baseUrl + (baseUrl.contains("?") ? "&v=" : "?v=") + System.currentTimeMillis();

		Request request = new Request.Builder()
				.url(requestUrl)
				.cacheControl(okhttp3.CacheControl.FORCE_NETWORK)
				.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Zealgains: Failed to fetch ban list from provided URL", e);
				clientThread.invokeLater(() ->
						client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Failed to fetch ban list.", null));
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				if (response.isSuccessful() && response.body() != null)
				{
					bannedPlayers.clear();
					String body = response.body().string();
					for (String token : body.split(","))
					{
						String trimmed = token.trim();
						if (trimmed.isEmpty()) continue;
						if (trimmed.startsWith("--")) continue;
						if (trimmed.contains("(Added:")) continue;
						if (trimmed.startsWith("<--")) continue;
						String name = cleanOsrsName(trimmed);
						if (!name.isEmpty()) bannedPlayers.add(name);
					}
					log.info("Zealgains: Successfully loaded {} banned players.", bannedPlayers.size());
					int count = bannedPlayers.size();
					clientThread.invokeLater(() -> {
						client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Successfully loaded " + count + " banned players.", null);
						refreshChatHighlights();
					});
				}
				else
				{
					clientThread.invokeLater(() ->
							client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Zealgains: Failed to load ban list. Response not successful.", null));
				}
				response.close();
			}
		});
	}

	@Provides
	ZealgainsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ZealgainsConfig.class);
	}
}

package com.zealgains;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;

public class ZealgainsObeliskOverlay extends Overlay
{
    private static final Color WARN_FILL   = new Color(255, 0, 0, 60);
    private static final Color WARN_BORDER = Color.RED;
    private static final Font  WARN_FONT   = new Font("Arial", Font.BOLD, 14);

    // World-coordinate bounding box of the Soul Obelisk tile square (SW 2205,2910 → NE 2208,2913).
    // Used as an absolute position lock so the polygon can never render anywhere else on the map.
    private static final int OBELISK_MIN_X = 2205;
    private static final int OBELISK_MAX_X = 2208;
    private static final int OBELISK_MIN_Y = 2910;
    private static final int OBELISK_MAX_Y = 2913;

    private final ZealgainsPlugin plugin;
    private final ZealgainsConfig config;
    private final Client client;

    @Inject
    ZealgainsObeliskOverlay(ZealgainsPlugin plugin, ZealgainsConfig config, Client client)
    {
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.highlightObelisk() || !plugin.isObeliskWarnActive()) return null;
        if (config.dumpOverlayFilter() == ZealgainsConfig.DumpOverlayFilter.SMART_FILTER
                && !config.alwaysShowDumpOverlay() && !plugin.isLocalPlayerInGame()) return null;

        GameObject obelisk = plugin.getTrackedObelisk();
        if (obelisk == null) return null;

        LocalPoint lp = obelisk.getLocalLocation();
        if (lp == null) return null;

        // Absolute position lock: only render if the obelisk's template world coordinates fall
        // within the known Soul Obelisk tile square. fromLocalInstance handles instanced regions
        // by mapping scene coordinates back to the template region coordinates.
        WorldPoint wp = WorldPoint.fromLocalInstance(client, lp);
        if (wp.getX() < OBELISK_MIN_X || wp.getX() > OBELISK_MAX_X
                || wp.getY() < OBELISK_MIN_Y || wp.getY() > OBELISK_MAX_Y) return null;

        // Hard tile-distance cap: reject if the obelisk is more than 15 tiles away in scene
        // space. This prevents perspective projection from producing a valid-looking polygon at
        // a completely wrong canvas position when the obelisk is at the scene edge.
        LocalPoint playerLp = client.getLocalPlayer() != null
                ? client.getLocalPlayer().getLocalLocation() : null;
        if (playerLp == null) return null;
        int distTiles = Math.max(Math.abs(lp.getX() - playerLp.getX()),
                                 Math.abs(lp.getY() - playerLp.getY()))
                        / Perspective.LOCAL_TILE_SIZE;
        if (distTiles > 15) return null;

        // Secondary guard: localToCanvas returns null when the tile center is outside the view
        // frustum — catch any remaining off-screen case the distance check didn't eliminate.
        net.runelite.api.Point tileCenter = Perspective.localToCanvas(client, lp, client.getPlane());
        if (tileCenter == null) return null;

        // Use a 3-tile area poly to cover the large obelisk footprint
        Polygon poly = Perspective.getCanvasTileAreaPoly(client, lp, 3);
        if (poly == null) return null;

        // Validate polygon position: all vertices must be within 200px of the projected tile center.
        // A 3×3 tile area is at most ~150px across at any zoom level, so any vertex further away
        // than 200px means the polygon has wrapped to the wrong canvas position.
        for (int i = 0; i < poly.npoints; i++)
        {
            if (Math.abs(poly.xpoints[i] - tileCenter.getX()) > 200
                    || Math.abs(poly.ypoints[i] - tileCenter.getY()) > 200) return null;
        }

        // Red fill + border
        graphics.setColor(WARN_FILL);
        graphics.fillPolygon(poly);
        graphics.setStroke(new BasicStroke(2));
        graphics.setColor(WARN_BORDER);
        graphics.drawPolygon(poly);

        // "DO NOT DUMP" text centered over the obelisk, with black shadow for readability
        String text = "DO NOT DUMP";
        graphics.setFont(WARN_FONT);
        FontMetrics fm = graphics.getFontMetrics();
        int x = (int) poly.getBounds().getCenterX() - fm.stringWidth(text) / 2;
        int y = (int) poly.getBounds().getCenterY() + fm.getAscent() / 2;
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 1, y + 1);
        graphics.setColor(Color.RED);
        graphics.drawString(text, x, y);

        return null;
    }
}

package com.zealgains;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.Map;
import java.util.Set;

public class ZealgainsPanel extends PluginPanel
{
    private final ZealgainsPlugin plugin;
    private final ZealgainsConfig config;

    private final JPanel redContainer = new JPanel();
    private final JPanel blueContainer = new JPanel();
    private final JPanel runnerContainer = new JPanel();
    private final JPanel runnerWrapper;
    private final JPanel statusPanel = new JPanel();
    private final JLabel timerLabel = new JLabel();
    private final JLabel scoreLabel = new JLabel();
    private final JLabel playersLabel = new JLabel();
    private final JLabel redHeader = new JLabel("Red Team");
    private final JLabel blueHeader = new JLabel("Blue Team");
    private final JLabel runnerHeader = new JLabel("Runners");

    public ZealgainsPanel(ZealgainsPlugin plugin, ZealgainsConfig config)
    {
        super(false);
        this.plugin = plugin;
        this.config = config;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel layoutPanel = new JPanel();
        layoutPanel.setLayout(new BoxLayout(layoutPanel, BoxLayout.Y_AXIS));
        layoutPanel.setBorder(new EmptyBorder(10, 10, 10, 10));
        layoutPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("Zealgains");
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        layoutPanel.add(title);
        layoutPanel.add(Box.createRigidArea(new Dimension(0, 6)));

        JLabel ranksNotice = new JLabel("Ask a rank for rules and methods");
        ranksNotice.setForeground(Color.LIGHT_GRAY);
        ranksNotice.setAlignmentX(Component.CENTER_ALIGNMENT);
        layoutPanel.add(ranksNotice);
        layoutPanel.add(Box.createRigidArea(new Dimension(0, 10)));

        // Timer, score, and player count
        statusPanel.setLayout(new BoxLayout(statusPanel, BoxLayout.Y_AXIS));
        statusPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        statusPanel.setVisible(false);

        timerLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        scoreLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        playersLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        statusPanel.add(timerLabel);
        statusPanel.add(scoreLabel);
        statusPanel.add(playersLabel);
        layoutPanel.add(statusPanel);
        layoutPanel.add(Box.createRigidArea(new Dimension(0, 10)));

        redContainer.setLayout(new BoxLayout(redContainer, BoxLayout.Y_AXIS));
        redContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        layoutPanel.add(createTeamSection(redHeader, redContainer));
        layoutPanel.add(Box.createRigidArea(new Dimension(0, 10)));

        blueContainer.setLayout(new BoxLayout(blueContainer, BoxLayout.Y_AXIS));
        blueContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        layoutPanel.add(createTeamSection(blueHeader, blueContainer));
        layoutPanel.add(Box.createRigidArea(new Dimension(0, 10)));

        runnerContainer.setLayout(new BoxLayout(runnerContainer, BoxLayout.Y_AXIS));
        runnerContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        runnerWrapper = createTeamSection(runnerHeader, runnerContainer);
        runnerWrapper.setVisible(false);
        layoutPanel.add(runnerWrapper);
        layoutPanel.add(Box.createRigidArea(new Dimension(0, 15)));

        JButton resetButton = new JButton("Reset Calls");
        resetButton.addActionListener(e ->
        {
            int result = JOptionPane.showConfirmDialog(
                this,
                "Clear all tracked calls and runners?",
                "Reset Calls",
                JOptionPane.YES_NO_OPTION
            );
            if (result == JOptionPane.YES_OPTION)
            {
                plugin.resetKillsFromUi();
            }
        });
        resetButton.setAlignmentX(Component.CENTER_ALIGNMENT);
        layoutPanel.add(resetButton);

        add(layoutPanel, BorderLayout.NORTH);
    }

    private JPanel createTeamSection(JLabel header, JPanel container)
    {
        JPanel wrapper = new JPanel(new BorderLayout());
        wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(new EmptyBorder(0, 0, 5, 0));
        wrapper.add(header, BorderLayout.NORTH);
        wrapper.add(container, BorderLayout.CENTER);
        return wrapper;
    }

    public void updateKills(Map<Integer, String> redKills, Map<Integer, String> blueKills)
    {
        int timeRemaining = plugin.getGameTimeRemaining(); // must be captured on the client thread
        SwingUtilities.invokeLater(() ->
        {
            redHeader.setForeground(config.overlayRedColor());
            blueHeader.setForeground(config.overlayBlueColor());

            redContainer.removeAll();
            blueContainer.removeAll();

            boolean inDumpPhase = (timeRemaining != -1 && timeRemaining <= 720) || config.enableCallsOutsideGame();
            boolean b5Visible = inDumpPhase && !redKills.containsKey(5);

            // R5 hidden when B5 is claimed
            for (int i = 1; i <= 5; i++)
            {
                if (i == 5 && blueKills.containsKey(5)) continue;
                JLabel label = new JLabel("Call " + i + ": " + redKills.getOrDefault(i, "-"));
                label.setForeground(config.overlayCallNameColor());
                redContainer.add(label);
            }

            // B5 only visible in dump phase when R5 is unclaimed
            for (int i = 1; i <= 5; i++)
            {
                if (i == 5 && !b5Visible) continue;
                JLabel label = new JLabel("Call " + i + ": " + blueKills.getOrDefault(i, "-"));
                label.setForeground(config.overlayCallNameColor());
                blueContainer.add(label);
            }

            revalidate();
            repaint();
        });
    }

    public void updateGameStatus(int seconds, int redScore, int blueScore)
    {
        int timeRemaining = plugin.getGameTimeRemaining(); // must be captured on the client thread
        int lobbyCount = plugin.getLobbyPlayerCount();
        SwingUtilities.invokeLater(() ->
        {
            boolean inGame = timeRemaining != -1;
            boolean showStatus = seconds >= 0;

            timerLabel.setForeground(config.overlayTimerColor());
            scoreLabel.setForeground(config.overlayScoreColor());
            playersLabel.setForeground(config.overlayLobbyCountColor());

            timerLabel.setVisible(showStatus && inGame);
            scoreLabel.setVisible(showStatus && inGame);

            if (showStatus && inGame)
            {
                timerLabel.setText(String.format("%d:%02d", seconds / 60, seconds % 60));
                scoreLabel.setText("Red: " + redScore + "  /  Blue: " + blueScore);
            }

            // Players: ## always shown during game; Lobby: ## opt-in outside game
            if (inGame && lobbyCount > 0)
            {
                playersLabel.setText("Players: " + lobbyCount);
                playersLabel.setVisible(true);
            }
            else if (!inGame && lobbyCount > 0 && config.showLobbyCount())
            {
                playersLabel.setText("Lobby: " + lobbyCount);
                playersLabel.setVisible(true);
            }
            else
            {
                playersLabel.setVisible(false);
            }

            statusPanel.setVisible(timerLabel.isVisible() || scoreLabel.isVisible() || playersLabel.isVisible());

            revalidate();
            repaint();
        });
    }

    public void updateRunners(Set<String> redRunners, Set<String> blueRunners)
    {
        SwingUtilities.invokeLater(() ->
        {
            runnerHeader.setForeground(config.overlayRunnersColor());
            runnerContainer.removeAll();

            boolean hasRunners = !redRunners.isEmpty() || !blueRunners.isEmpty();
            runnerWrapper.setVisible(hasRunners);

            if (!redRunners.isEmpty())
            {
                JLabel label = new JLabel("Red: " + String.join(", ", redRunners));
                label.setForeground(config.overlayRedColor());
                runnerContainer.add(label);
            }
            if (!blueRunners.isEmpty())
            {
                JLabel label = new JLabel("Blue: " + String.join(", ", blueRunners));
                label.setForeground(config.overlayBlueColor());
                runnerContainer.add(label);
            }

            revalidate();
            repaint();
        });
    }
}
